ALTER TABLE `expensecategory` ADD `status` INT NULL DEFAULT '1' COMMENT '0=inactive\r\n1=active', ADD `is_deleted` INT NULL DEFAULT '0' COMMENT '0=not deleted\r\n1=deleted' AFTER `status`, ADD `is_default` INT NULL DEFAULT '0' COMMENT '0=not default\r\n1=defualt' AFTER `is_deleted`, ADD `created_date` DATE NULL DEFAULT CURRENT_TIMESTAMP AFTER `is_default`, ADD `created_by` INT NULL AFTER `created_date`, ADD `modified_by` INT NULL AFTER `created_by`, ADD `modified_date` DATE NULL DEFAULT CURRENT_TIMESTAMP AFTER `modified_by`;